const OCEAN_BG = "#AAD3DF";
const CRI_FILL = "#EEF2E3";

function terrainNoise(x, y) {
  return (
    Math.sin(x * 0.011 + Math.sin(y * 0.007) * 1.7) * 0.55 +
    Math.sin(y * 0.013 + Math.sin(x * 0.005) * 2.1) * 0.45 +
    Math.sin((x + y) * 0.021) * 0.18 +
    Math.sin((x - y) * 0.017 + 1.3) * 0.14
  );
}

const TerrainContourLayer = L.GridLayer.extend({
  createTile(coords) {
    const tile = document.createElement("canvas");
    const size = this.getTileSize();
    tile.width = size.x;
    tile.height = size.y;
    if (coords.z < 12) return tile;
    const ctx = tile.getContext("2d");
    const scale = Math.pow(2, coords.z - 15);
    const ox = coords.x * size.x;
    const oy = coords.y * size.y;
    const step = 2;
    const bands = 9;
    ctx.fillStyle = "rgba(108, 148, 92, 0.22)";
    for (let y = 0; y < size.y; y += step) {
      for (let x = 0; x < size.x; x += step) {
        const v = terrainNoise((ox + x) / scale, (oy + y) / scale);
        const b0 = Math.floor(v * bands);
        const bx = Math.floor(terrainNoise((ox + x + step) / scale, (oy + y) / scale) * bands);
        const by = Math.floor(terrainNoise((ox + x) / scale, (oy + y + step) / scale) * bands);
        if (b0 !== bx || b0 !== by) {
          ctx.fillRect(x, y, 1.6, 1.6);
        }
      }
    }
    ctx.globalCompositeOperation = "destination-over";
    for (let y = 0; y < size.y; y += 8) {
      for (let x = 0; x < size.x; x += 8) {
        const v = terrainNoise(((ox + x) / scale) * 0.6 + 900, ((oy + y) / scale) * 0.6 - 400);
        if (v > 0.15) {
          ctx.fillStyle = `rgba(150, 196, 120, ${Math.min(0.32, (v - 0.15) * 0.5)})`;
          ctx.fillRect(x, y, 8, 8);
        }
      }
    }
    return tile;
  },
});

const NaturalEarthBaseLayer = L.Layer.extend({
  initialize(options) {
    L.setOptions(this, {
      ...(options || {}),
      attribution: "Mapa base: Natural Earth",
    });
  },
  onAdd(map) {
    [
      ["akLand", 150],
      ["akTerrain", 160],
      ["akLines", 170],
      ["akLabels", 180],
    ].forEach(([name, zIndex]) => {
      if (!map.getPane(name)) {
        const pane = map.createPane(name);
        pane.style.zIndex = zIndex;
        pane.style.pointerEvents = "none";
      }
    });
    map.getContainer().style.background = OCEAN_BG;
    const makeRenderer = (pane) => L.svg({ pane, padding: 0.5 });
    const landRenderer = makeRenderer("akLand");
    const linesRenderer = makeRenderer("akLines");
    this._group = L.layerGroup([
      L.geoJSON(Qi.land, {
        pane: "akLand",
        renderer: landRenderer,
        interactive: false,
        style: (feature) => ({
          stroke: true,
          color: "#C9D3BE",
          weight: 1,
          fillColor: feature.properties.ADM0_A3 === "CRI" ? CRI_FILL : "#E4E7DD",
          fillOpacity: 1,
        }),
      }),
      new TerrainContourLayer({
        pane: "akTerrain",
        tileSize: 256,
        updateWhenZooming: false,
      }),
      L.geoJSON(Qi.lakes, {
        pane: "akLines",
        renderer: linesRenderer,
        interactive: false,
        style: { stroke: false, fillColor: OCEAN_BG, fillOpacity: 1 },
      }),
      L.geoJSON(Qi.rivers, {
        pane: "akLines",
        renderer: linesRenderer,
        interactive: false,
        style: { color: OCEAN_BG, weight: 1.6, opacity: 1 },
      }),
      L.geoJSON(Qi.prov, {
        pane: "akLines",
        renderer: linesRenderer,
        interactive: false,
        style: { color: "#B8B0C4", weight: 1, dashArray: "4 4", fill: false },
      }),
      L.geoJSON(Qi.roads, {
        pane: "akLines",
        renderer: linesRenderer,
        interactive: false,
        style: { color: "#F6D9A8", weight: 2, opacity: 0.95 },
      }),
      L.geoJSON(Qi.places, {
        pane: "akLabels",
        interactive: false,
        pointToLayer: (feature, latlng) =>
          L.marker(latlng, {
            pane: "akLabels",
            interactive: false,
            keyboard: false,
            icon: L.divIcon({
              className: "ak-place-label",
              html: `<span>${feature.properties.name}</span>`,
              iconSize: [0, 0],
            }),
          }),
      }),
    ]);
    this._group.addTo(map);
    this._zoomLabels = () => {
      const pane = map.getPane("akLabels");
      if (pane) {
        pane.style.display = map.getZoom() <= 10 ? "" : "none";
      }
    };
    map.on("zoomend", this._zoomLabels);
    this._zoomLabels();
  },
  getAttribution() {
    return this.options.attribution;
  },
  onRemove(map) {
    map.off("zoomend", this._zoomLabels);
    if (this._group) {
      this._group.remove();
    }
  },
});

export function createNaturalEarthTileLayer(options) {
  return new NaturalEarthBaseLayer(options);
}
